import OpenAI from "openai";
import { init, shutdown, span, wrapOpenAI } from "neatlogs";
import {
  ChatCompletionMessageParam,
  ChatCompletionTool,
} from "openai/resources/chat/completions";

function requireEnv(name: string): string {
  const value = process.env[name];
  if (!value) throw new Error(`Set ${name} in .env`);
  return value;
}

const model = requireEnv("OPENAI_MODEL");
const apiKey = requireEnv("OPENAI_API_KEY");

await init({
  apiKey: requireEnv("NEATLOGS_API_KEY"),
  workflowName: "npm-advisor",
});

const client = wrapOpenAI(
  new OpenAI({
    baseURL: "https://api.aicredits.in/v1",
    apiKey: apiKey,
  }),
);

const MAX_STEPS = 8;

const tools: ChatCompletionTool[] = [
  {
    type: "function",
    function: {
      name: "search_packages",
      description:
        "Search the npm registry by keywords. Returns the 8 most downloaded matches with name, description and weekly downloads. " +
        'Results depend heavily on wording, so try 2 or 3 phrasings (e.g. "react form", "react form library", "react hook form").',
      parameters: {
        type: "object",
        properties: {
          query: {
            type: "string",
            description: 'Search terms, e.g. "date formatting"',
          },
        },
        required: ["query"],
        additionalProperties: false,
      },
      strict: true,
    },
  },
  {
    type: "function",
    function: {
      name: "get_package_info",
      description:
        "Look up one npm package by exact name. Returns description, latest version, last publish date, license, " +
        "weekly downloads and whether it is deprecated, or found: false if no such package exists. " +
        "Use it to check packages you suspect exist but search missed, and to verify your top picks before recommending.",
      parameters: {
        type: "object",
        properties: {
          name: {
            type: "string",
            description:
              'Exact package name, e.g. "formik" or "@tanstack/react-form"',
          },
        },
        required: ["name"],
        additionalProperties: false,
      },
      strict: true,
    },
  },
];

interface SearchResult {
  name: string;
  description: string;
  weeklyDownloads: number;
}

interface NpmSearchResponse {
  objects: {
    package: { name: string; description?: string; date?: string };
    downloads?: { weekly: number };
  }[];
}

interface NpmLatestManifest {
  version: string;
  description?: string;
  license: string;
  deprecated: string;
}

type PackageInfo =
  | { found: false; name: string }
  | {
      found: true;
      name: string;
      description: string;
      latestVersion: string;
      lastPublished: string | null;
      license: string | null;
      weeklyDownloads: number | null;
      deprecated: string | null;
    };

const searchPackages = span(
  { kind: "TOOL", toolName: "search_packages" },
  async (query: string): Promise<SearchResult[]> => {
    const url = `https://registry.npmjs.org/-/v1/search?text=${encodeURIComponent(query)}&size=25`;

    const res = await fetch(url);
    if (!res.ok) throw new Error(`npm search failed with status ${res.status}`);

    const data = (await res.json()) as NpmSearchResponse;

    return data.objects
      .map((o) => ({
        name: o.package.name,
        description: o.package.description ?? "",
        weeklyDownloads: o.downloads?.weekly ?? 0,
      }))
      .sort((a, b) => b.weeklyDownloads - a.weeklyDownloads)
      .slice(0, 8);
  },
);

const getPackageInfo = span(
  { kind: "TOOL", toolName: "get_package_info" },
  async (name: string): Promise<PackageInfo> => {
    const encoded = encodeURIComponent(name).replace("%40", "@");
    const [latestRes, searchRes] = await Promise.all([
      fetch(`https://registry.npmjs.org/${encoded}/latest`),
      fetch(
        `https://registry.npmjs.org/-/v1/search?text=${encodeURIComponent(name)}&size=5`,
      ),
    ]);

    if (latestRes.status === 404) return { found: false, name };
    if (!latestRes.ok)
      throw new Error(
        `npm lookup for ${name} failed with status ${latestRes.status}`,
      );

    const latest = (await latestRes.json()) as NpmLatestManifest;

    const search = searchRes.ok
      ? ((await searchRes.json()) as NpmSearchResponse)
      : { objects: [] };

    const match = search.objects.find((o) => o.package.name === name);

    return {
      found: true,
      name,
      description: latest.description ?? "",
      latestVersion: latest.version,
      lastPublished: match?.package.date ?? null,
      license: latest.license ?? null,
      weeklyDownloads: match?.downloads?.weekly ?? null,
      deprecated: latest.deprecated ?? null,
    };
  },
);

async function runTool(name: string, rawArgs: string): Promise<string> {
  const args: unknown = JSON.parse(rawArgs);

  if (name === "search_packages" && isQueryArgs(args)) {
    return JSON.stringify(await searchPackages(args.query));
  }

  if (name === "get_package_info" && isNameArgs(args)) {
    return JSON.stringify(await getPackageInfo(args.name));
  }

  return JSON.stringify({ error: `Unknown tool or bad args: ${name}` });
}

function isQueryArgs(value: unknown): value is { query: string } {
  return (
    typeof value === "object" &&
    value !== null &&
    "query" in value &&
    typeof value.query === "string"
  );
}

function isNameArgs(value: unknown): value is { name: string } {
  return (
    typeof value === "object" &&
    value !== null &&
    "name" in value &&
    typeof value.name === "string"
  );
}

const runAgent = span(
  { kind: "AGENT", name: "npm_advisor" },
  async (question: string): Promise<string> => {
    const messages: ChatCompletionMessageParam[] = [
      {
        role: "system",
        content:
          "You help developers pick npm packages. Use tools to get real data before recommending. " +
          "Search first, then call get_package_info on your top 3 candidates, plus any well-known package search missed. " +
          "Weigh weekly downloads, last publish date and deprecation. Leave out helper packages that extend another library. " +
          "Give one clear recommendation and at most two alternatives, each with its downloads and last publish date.",
      },
      { role: "user", content: question },
    ];

    for (let step = 1; step <= MAX_STEPS; step++) {
      const res = await client.chat.completions.create({
        model,
        messages,
        tools,
      });

      const msg = res.choices[0]?.message;
      if (!msg) throw new Error("Model returned no message");
      messages.push(msg);

      if (!msg.tool_calls?.length) return msg.content ?? "";

      const calls = msg.tool_calls.filter((call) => call.type === "function");
      const results = await Promise.all(
        calls.map(async (call) => {
          console.log(
            `[step ${step}] ${call.function.name}(${call.function.arguments})`,
          );
          return {
            id: call.id,
            content: await runTool(call.function.name, call.function.arguments),
          };
        }),
      );
      for (const { id, content } of results) {
        messages.push({ role: "tool", tool_call_id: id, content });
      }
    }
    return `Stopped after ${MAX_STEPS} steps without a final answer.`;
  },
);

const advise = span({ kind: "WORKFLOW", name: "advise" }, runAgent);

const question =
  process.argv.slice(2).join(" ") ||
  "Which date library should I use for a Next.js app?";
try {
  console.log(await advise(question));
} finally {
  await shutdown();
}
# Architecture

Mekiki is a command line agent that recommends npm packages. You ask a question, it looks up real registry data through tools, and it answers with one pick and up to two alternatives.

## Files

| File              | Purpose                                                                  |
| ----------------- | ------------------------------------------------------------------------ |
| `agent.ts`        | The whole agent: tool schemas, tool functions, and the loop              |
| `.env`            | `OPENAI_API_KEY`, `OPENAI_MODEL` and `NEATLOGS_API_KEY`, never committed |
| `architecture.md` | How the agent works                                                      |
| `decisions.md`    | Why it works that way, and what we rejected                              |

## The loop

`runAgent` keeps a `messages` array and calls the model with it and the tool list. If the reply asks for tools, the loop runs them in parallel with `Promise.all`, appends each result tagged with its `tool_call_id`, and calls the model again. If the reply has no tool calls, that text is the answer. `MAX_STEPS` caps the number of model turns, not tool calls, since one turn can request several tools in parallel.

```mermaid
flowchart LR
  Q[Question] --> M[Model call]
  M -->|tool_calls| T[Run tools]
  T -->|results by tool_call_id| M
  M -->|no tool_calls| A[Answer]
```

## Tools

Each tool has two halves. The schema in `tools` is what the model reads. The function is plain TypeScript that the loop runs on the model's behalf.

| Tool                     | Source                                                  | Returns                                                                                     |
| ------------------------ | ------------------------------------------------------- | ------------------------------------------------------------------------------------------- |
| `search_packages(query)` | npm search API, 25 results                              | Top 8 by weekly downloads: name, description, downloads                                     |
| `get_package_info(name)` | `/<name>/latest` plus an exact-name search, in parallel | Description, version, last publish date, license, downloads, deprecation, or `found: false` |

Tool results go back as JSON strings and stay in the context for every later turn, so each tool returns only the fields the model needs.

## Tracing

Neatlogs records every run as one trace:

```
WORKFLOW advise
└─ AGENT npm_advisor
   ├─ LLM (one per model turn, from wrapOpenAI)
   ├─ TOOL search_packages
   └─ TOOL get_package_info
```

`init()` runs once at startup. `openai` is the only OpenAI client, wrapped with `wrapOpenAI`, so no model call escapes the trace. Tool functions are wrapped with `span({ kind: 'TOOL' })`, which records their inputs and outputs. `shutdown()` runs in a `finally` block so spans get sent even when the run crashes.

## Known gaps

- If npm returns an error status, the tool throws and the whole run crashes. The model never gets a chance to recover.
- Deprecated packages often drop out of npm search, so their publish date and downloads come back `null`.
- Search results depend heavily on wording. The tool description asks the model to try several phrasings.
# Decisions

Newest first. Each entry says what we chose, why, and what we turned down.

## 2026-10-07: Run tool calls in parallel

The model often asks for several tools in one turn, but the loop ran them one at a time with `await` inside `for...of`. The answer was the same either way, so only the trace timeline showed it: each tool span started the moment the previous one ended. Now the loop runs them with `Promise.all`. Each result comes back paired with its `tool_call_id`, so order can't get mixed up.

Measured on the form question, comparing runs with the same number of calls (3 searches, then 3 package lookups):

|               | Before | After  |
| ------------- | ------ | ------ |
| Time in tools | 6.3 s  | 2.3 s  |
| Total run     | 14.0 s | 10.7 s |

Before: trace `ad6ff271963c7520c05d8bf6c328352a`. After: trace `06f94df4908c636d9e010c1031cbc07e`. Two more runs after the fix made only 2 searches and spent 2.8 s and 2.9 s in tools. Answer quality didn't change, which is what we expected from a speed-only fix.

The model calls now take most of the time. The final call alone runs 4 to 5 seconds, since it writes 250 to 300 tokens.

## 2026-10-07: Manual Neatlogs setup, not the wizard

Neatlogs offers `npx @neatlogs/wizard@latest`, which edits your code for you. We added tracing by hand so we know what every line does before the hackathon, where we'll have to shape traces ourselves.

The trace tree is `WORKFLOW advise` > `AGENT npm_advisor` > `LLM` spans from `wrapOpenAI` and `TOOL` spans from `span()`. One CLI run is one trace.

The API key comes from `NEATLOGS_API_KEY` in `.env`. The dashboard snippet hardcodes it in `init()`, which would put it in a public repo.

`shutdown()` runs in a `finally` block. Spans flush every 5 seconds, so a short run or a crash could exit before they're sent. The `finally` matters most for crashes, since those are the traces we most want to see.

## 2026-10-07: One `get_package_info` tool instead of two

We merged the planned `get_package_info` and `get_downloads` into one tool. The model never wants one of those facts without the others, and every extra tool is one more choice it can get wrong. The cost is two HTTP requests inside one tool call.

## 2026-10-07: `/latest` plus search, not the full package document

The full document for `react-hook-form` is 5.2 MB because it lists every version ever published. `/latest` is 5 KB and has version, description, license and deprecation, but no publish date. An exact-name search fills in publish date and weekly downloads. Both run in parallel.

Rejected: fetching the latest version first and then its description. `/latest` returns both in one request, so a second call adds nothing.

Rejected: the abbreviated document (`application/vnd.npm.install-v1+json`). Still 2.6 MB, and it only has a `modified` date, which also changes on edits that aren't releases.

## 2026-10-07: A missing package is data, not an error

`get_package_info` returns `{ found: false }` on a 404. A model guessing a package name that doesn't exist is an expected outcome, and it should learn that and move on. A 500 or a network failure is different, and it still throws.

## 2026-10-07: Leave the crash on npm errors in, for now

A failed npm request crashes the run instead of returning the error to the model. We left it on purpose so we can trigger it and find it in Neatlogs traces in step 4.

## 2026-10-07: Fetch 25 search results, sort by downloads, keep 8

npm search ranks by text match, not popularity. With 5 results, "React form library" missed `react-hook-form` (70M weekly downloads) entirely. With 25 it came first after sorting. Keeping 8 limits how much text rides along in the context on every later turn.

## 2026-10-07: Phrasing advice lives in the tool description

"react form" and "react form library" return very different results, so the tool description tells the model to try 2 or 3 phrasings. We put this in the tool description rather than the system prompt because it's about using this one tool, and it travels with the tool if we reuse it.

## 2026-10-07: Model name comes from `OPENAI_MODEL`

Model names change often. An env var lets us swap models without touching code. We use `gpt-4o-mini`, a cheap model that fails often enough to teach us something.

## 2026-10-07: `tsx` and Node's `--env-file`

`tsx` runs TypeScript with no build step. Node 22's `--env-file` loads `.env`, so we skipped `dotenv`. `openai` 7.x needs Node 22 or later anyway.
# Mekiki
An npm package advisor agent. Ask which library to use, it checks the registry and download numbers, then recommends one.
